  // Changelog v2.23.0
  changelog_r_2_23_0_t: 'Bộ chọn AI Coach 4 cấp độ, Tự động xoay model, Quét ảnh ghi chú & Kho ứng dụng mới',
  changelog_r_2_23_0_h1: 'Nâng cấp AI Study Coach với bộ chọn 4 cấp độ kiểu ChatGPT/Claude (Tức thì, Cân bằng, Chuyên sâu, Tối đa) và khung chat toàn chiều ngang',
  changelog_r_2_23_0_h2: 'Thêm công cụ Quét ảnh ghi chú giúp tách chữ viết tay, bảng lớp và công thức toán học thành Markdown lưu thẳng vào Ghi chú',
  changelog_r_2_23_0_h3: 'Thiết kế lại Kho ứng dụng sinh động với thẻ xem trước trực quan, bộ công cụ gợi ý 1 chạm và tự động xoay vòng model khi chạm hạn mức',
  changelog_r_2_23_0_d1: 'Mở AI Study Coach để chọn giữa Tức thì, Cân bằng, Chuyên sâu hoặc Tối đa kèm thẻ hạn mức rõ ràng và khung soạn thảo rộng rãi nhiều dòng.',
  changelog_r_2_23_0_d2: 'Mở Quét ảnh ghi chú từ Kho ứng dụng, Bảng lệnh (⌘K) hoặc thanh Ghi chú để kéo thả hoặc dán ảnh và trích xuất nội dung cùng công thức KaTeX bằng nhóm model tiết kiệm nhất.',
  changelog_r_2_23_0_d3: 'Mọi tác vụ AI tự động đổi sang model dự phòng trong danh sách cho phép khi một model chạm giới hạn (không gọi nhầm model TTS), quét Gmail dùng nhóm nhanh và Kho ứng dụng có thẻ xem trước cùng Bộ công cụ gợi ý.',

  // Changelog v2.23.1
  changelog_r_2_23_1_t: 'Dừng đồng bộ Gmail liên tục & Khắc phục AI đọc và phân loại email',
  changelog_r_2_23_1_h1: 'Ngừng tình trạng tự quét lại Gmail liên tục do chuyển cửa sổ, làm mới token và chu kỳ nền quá ngắn',
  changelog_r_2_23_1_h2: 'Sửa lỗi tương thích JSON mode trên Gemma để AI đọc, phân loại thư và trích xuất hạn bài tập ổn định',
  changelog_r_2_23_1_h3: 'Bổ sung dự phòng tự động qua Gemini Flash, Groq chia nhỏ lô và khóa BYOK cá nhân khi máy chủ bận',
  changelog_r_2_23_1_d1: 'Đồng bộ nền được giãn thành mỗi 5 phút kèm thời gian chờ 5 phút cho tự động đồng bộ Gmail và 2 phút khi quay lại tab; nút Làm mới hộp thư vẫn chạy ngay lập tức khi bạn bấm.',
  changelog_r_2_23_1_d2: 'Loại bỏ tham số JSON mode không hỗ trợ khi gọi Gemma 4 và tự động dự phòng sang Gemini Flash hoặc Groq (có chia nhỏ lô thư) để email được phân loại vào Bài tập, Thông báo và Khác thay vì báo lỗi.',
  changelog_r_2_23_1_d3: 'Nếu lần trước AI gặp lỗi khi đọc thư, bấm Làm mới hộp thư sẽ thử phân loại lại ngay và tận dụng khóa Gemini/Groq cá nhân nếu máy chủ chưa sẵn sàng.',

  // Changelog v2.23.2
  changelog_r_2_23_2_t: 'Quét AI tăng dần cho Gmail & Đọc toàn bộ thư kể cả Spam',
  changelog_r_2_23_2_h1: 'Khi bấm Làm mới hộp thư, AI chỉ quét thư mới hoặc thư chưa từng đọc và giữ nguyên kết quả các thư đã phân loại',
  changelog_r_2_23_2_h2: 'AI nay đọc toàn bộ email kể cả thư nằm trong Spam, Quảng cáo và Mạng xã hội để không bỏ sót thông báo quan trọng',
  changelog_r_2_23_2_h3: 'Bài tập hoặc lịch thi được AI phát hiện trong thư mục Spam/Quảng cáo vẫn được giữ lại để bạn kiểm tra',
  changelog_r_2_23_2_d1: 'Bấm Làm mới hộp thư sẽ lấy danh sách thư mới nhất nhưng giữ nguyên các thư đã được AI đọc xong, chỉ gửi thư mới hoặc thư chưa quét/lỗi trước đó cho AI.',
  changelog_r_2_23_2_d2: 'Truy vấn Gmail và bộ lọc AI nay bao gồm cả hộp thư Spam bên cạnh Hộp thư đến (Chính, Quảng cáo, Mạng xã hội).',
  changelog_r_2_23_2_d3: 'Nếu AI phát hiện bài tập hoặc bài kiểm tra trong thư bị Gmail gắn nhãn Spam/Quảng cáo, hệ thống giữ nguyên phân loại và đưa vào mục Cần bạn xem.',

